from __future__ import annotations

import os
from datetime import date, datetime, timezone

from chainguard_fetchers.http import FetchError, get_json

BASE = "https://services9.arcgis.com/weJ1QsnbMYJlCHdG/ArcGIS/rest/services"
PORTS = "PortWatch_ports_database"
CHOKEPOINTS = "PortWatch_chokepoints_database"
DISRUPTIONS = "portwatch_disruptions_database"
DAILY_PORTS = "Daily_Ports_Data"
DAILY_CHOKEPOINTS = "Daily_Chokepoints_Data"
PAGE_SIZE = 1000  # server maxRecordCount


class PortWatchTokenRequired(FetchError):
    """The daily traffic layers need an ArcGIS token (set PORTWATCH_ARCGIS_TOKEN)."""


def _ms_to_iso(ms) -> str | None:
    if ms in (None, ""):
        return None
    return datetime.fromtimestamp(int(ms) / 1000, tz=timezone.utc).isoformat()


def _ms_to_date(ms) -> str | None:
    iso = _ms_to_iso(ms)
    return iso[:10] if iso else None


def query_params(where: str = "1=1", offset: int = 0, token: str | None = None,
                 order_by: str | None = None) -> dict:
    p = {"where": where, "outFields": "*", "returnGeometry": "false", "f": "json",
         "resultOffset": offset, "resultRecordCount": PAGE_SIZE}
    if order_by:
        p["orderByFields"] = order_by
    if token:
        p["token"] = token
    return p


def query_layer(service: str, where: str = "1=1", token: str | None = None,
                order_by: str | None = None, max_pages: int = 200, **http_kwargs) -> list[dict]:
    """Page through an ArcGIS layer; returns the raw `attributes` dicts."""
    url = f"{BASE}/{service}/FeatureServer/0/query"
    out: list[dict] = []
    for page in range(max_pages):
        payload = get_json(url, query_params(where, page * PAGE_SIZE, token, order_by), **http_kwargs)
        err = payload.get("error")
        if err:  # ArcGIS reports errors inside an HTTP 200
            if err.get("code") in (498, 499):
                raise PortWatchTokenRequired(f"{service}: {err.get('message')} (set PORTWATCH_ARCGIS_TOKEN)")
            raise FetchError(f"{service}: ArcGIS error {err.get('code')}: {err.get('message')}")
        feats = payload.get("features") or []
        out.extend(f.get("attributes") or {} for f in feats)
        if not payload.get("exceededTransferLimit") or not feats:
            break
    return out


# ── open layers ───────────────────────────────────────────────────────────────

def parse_locations(attrs: list[dict], kind: str) -> list[dict]:
    """Ports or chokepoints (same schema). kind = 'port' | 'chokepoint'."""
    return [{
        "location_id": a["portid"],
        "kind": kind,
        "name": a.get("portname"),
        "country": a.get("country"),
        "iso3": a.get("ISO3"),
        "locode": a.get("LOCODE"),
        "lat": a.get("lat"),
        "lon": a.get("lon"),
        "vessel_count_total": a.get("vessel_count_total"),
        "top_industry": a.get("industry_top1"),
    } for a in attrs if a.get("portid")]


def fetch_ports(**http_kwargs) -> list[dict]:
    return parse_locations(query_layer(PORTS, **http_kwargs), "port")


def fetch_chokepoints(**http_kwargs) -> list[dict]:
    return parse_locations(query_layer(CHOKEPOINTS, **http_kwargs), "chokepoint")


def parse_disruptions(attrs: list[dict]) -> list[dict]:
    return [{
        "event_id": a["eventid"],
        "event_type": a.get("eventtype"),
        "name": a.get("eventname"),
        "alert_level": a.get("alertlevel"),
        "country": a.get("country"),
        "from_date": _ms_to_iso(a.get("fromdate")),
        "to_date": _ms_to_iso(a.get("todate")),
        "edit_date": _ms_to_iso(a.get("editdate")),
        "severity_text": a.get("severitytext"),
        "lat": a.get("lat"),
        "lon": a.get("long"),
        "affected_ports": a.get("affectedports"),
        "n_affected_ports": a.get("n_affectedports"),
    } for a in attrs if a.get("eventid") is not None]


def fetch_disruptions(since: date | None = None, **http_kwargs) -> list[dict]:
    """Disruptions edited on/after `since` (incremental)."""
    where = "1=1" if since is None else f"editdate >= DATE '{since.isoformat()}'"
    return parse_disruptions(query_layer(DISRUPTIONS, where=where, **http_kwargs))


# ── token-gated daily traffic ─────────────────────────────────────────────────

def parse_daily(attrs: list[dict], id_field: str = "portid") -> list[dict]:
    """Daily rows. Unknown numeric columns are passed through unchanged (name -> value)."""
    rows = []
    for a in attrs:
        if a.get(id_field) is None or a.get("date") is None:
            continue
        row = {k: v for k, v in a.items() if k not in ("ObjectId", "date", "year", "month", "day", id_field)}
        row.update({"location_id": a[id_field], "day": _ms_to_date(a["date"])})
        rows.append(row)
    return rows


def _daily(service: str, id_field: str, since: date | None, token: str | None, **http_kwargs) -> list[dict]:
    token = token or os.getenv("PORTWATCH_ARCGIS_TOKEN")
    if not token:
        raise PortWatchTokenRequired("PORTWATCH_ARCGIS_TOKEN is not set")
    where = "1=1" if since is None else f"date >= DATE '{since.isoformat()}'"
    return parse_daily(query_layer(service, where=where, token=token, order_by="date ASC", **http_kwargs), id_field)


def fetch_daily_ports(since: date | None = None, token: str | None = None, **http_kwargs) -> list[dict]:
    return _daily(DAILY_PORTS, "portid", since, token, **http_kwargs)


def fetch_daily_chokepoints(since: date | None = None, token: str | None = None, **http_kwargs) -> list[dict]:
    return _daily(DAILY_CHOKEPOINTS, "portid", since, token, **http_kwargs)
